IF NOT EXISTS (SELECT 1 FROM store_configurations WHERE field_name = 'promo_banner_message')
INSERT INTO store_configurations (field_name, field_value)
VALUES ('promo_banner_message', 'Free shipping on orders over USD 100.00 - Use COUPON for 10% off');

IF NOT EXISTS (SELECT 1 FROM store_configurations WHERE field_name = 'coupon_code')
INSERT INTO store_configurations (field_name, field_value)
VALUES ('coupon_code', 'COUPON');

IF NOT EXISTS (SELECT 1 FROM store_configurations WHERE field_name = 'coupon_discount_percentage')
INSERT INTO store_configurations (field_name, field_value)
VALUES ('coupon_discount_percentage', '10');
